E["npc:felgur-twocuts"] = {t="npc",n="Felgur Twocuts",z="desolace",s="Felgur Twocuts is a blunt orc scout stationed at Ghost Walker Post in Desolace. He coordinates Horde efforts against the regional centaur clans.",h="Felgur Twocuts is a blunt orc scout stationed at Ghost Walker Post in Desolace.",sec={{t="A Gruff Outpost Scout",b="Standing watch amid the bleak expanse of Ghost Walker Post in central Desolace, Felgur Twocuts has little patience for pleasantries. As a forward scout for the Horde, he assesses the threats facing travelers and settlers venturing west through the mountains, particularly the local Kolkar centaur.",sp=0},{t="War on the Centaur",b="Felgur directs Horde champions to cull the local centaur chieftains and collect bounties on the warring tribes who threaten to overrun the region. He is a central contact for anyone seeking to secure the Horde's foothold in Desolace.",sp=0}},faq={{q="Who is Felgur Twocuts?",a="Felgur Twocuts is an orc scout and quest giver stationed at Ghost Walker Post, the Horde's forward encampment in Desolace.",al={"felgur twocuts who","who is felgur"},it="identity"},{q="Where can I find Felgur Twocuts?",a="He is located at Ghost Walker Post, just north of the central road running through Desolace.",al={"felgur twocuts location","where is felgur","where is felgur twocuts"},gp=true},{q="What tasks does Felgur Twocuts give?",a="Felgur enlists Horde adventurers to strike at the local Kolkar centaur, hunt down Khan Dez'hepah, and collect bounties on hostile centaur.",al={"felgur quests","what does felgur want"},gp=true},{q="Why is Felgur so curt with visitors?",a="Desolace is a dangerous and unforgiving wasteland surrounded by hostile centaur clans. Stationed in an isolated post, Felgur has no time for idle chatter and prefers to focus strictly on survival and martial duty.",al={"why is felgur rude","make it quick felgur"}},{q="Whose side is Felgur Twocuts on?",a="Felgur is a proud member of the Horde, stationed far out on the frontier to advance their interests and defend their encampments against regional threats.",al={"felgur twocuts faction","is felgur horde","who does felgur serve"},it="side",add="f5a09a6e"},{q="What does Felgur Twocuts want?",a="Felgur seeks to curb the hostile centaur clans threatening the Horde in Desolace. He enlists capable champions to collect bounties and confront Khan Dez'hepah.",al={"felgur twocuts goal","what is felgur trying to do","what does felgur need"},it="wants",add="8c623583"},{q="Why is Felgur Twocuts stationed here?",a="Felgur is garrisoned at Ghost Walker Post to monitor the local centaur tribes and direct action against threats to the Horde's foothold in Desolace.",al={"why is felgur twocuts at ghost walker post","felgur purpose here","why is felgur out here"},it="why_here",add="a5d710fc"}},ang={["faction:Horde"]="Felgur acts as a vital operations liaison at Ghost Walker Post, helping the Horde push back aggressive centaur tribes in Desolace.",["race:Orc"]="True to standard orcish pragmatism in dangerous borderlands, Felgur values strength, speed, and immediate results over idle conversation."},kw={"centaur bounty","desolace","felgur twocuts","ghost walker post","horde","kolkar","orc"},rel={"subzone:ghost-walker-post","zone:desolace","topic:centaur","quest:1362","topic:horde","zone:barrens"},src={"Felgur Twocuts"}}
E["npc:kreldig-ungor"] = {t="npc",n="Kreldig Ungor",z="desolace",s="Kreldig Ungor is an enterprising dwarven operative representing Reclaimers Inc., stationed high among the crags of Nijel's Point in Desolace. Tasked with managing field operations in the barren wasteland, he hires Alliance adventurers to recover lost cargo and secure valuable local reagents. His salvage and recovery contracts make him a central contact for travelers navigating the hostile region.",h="Kreldig Ungor is an enterprising dwarven operative representing Reclaimers Inc., stationed high among the...",sec={{t="Field Agent in the Wastes",b="Nijel's Point offers the Alliance a rare sanctuary amid the blighted canyons of Desolace, making it an ideal staging ground for commercial opportunists like Kreldig Ungor. Representing Reclaimers Inc., Kreldig has ventured far from the safety of Khaz Modan into a desolate wilderness contested by centaur clans, demons, and the Horde. Where others see ruin and ash, Kreldig sees untapped profit and lost assets ripe for recovery.",sp=0},{t="The Karnitol Contract",b="A primary venture bringing Kreldig to Desolace involves the lost vessel of Karnitol, which wrecked along the treacherous western coast. Karnitol's shipment held prized goods, and Kreldig orchestrates efforts to track down the debris and retrieve the scattered cargo before scavengers or coastal sea giants can claim it all.",sp=0},{t="Harvesting Local Reagents",b="Beyond maritime salvage, Kreldig oversees the procurement of Desolace's strange biological and mineral treasures for Reclaimers Inc. The harsh environment breeds unique fauna and flora, whose parts fetch high prices among alchemists and engineers back in the Eastern Kingdoms. Adventurers willing to brave the wasteland's predators find steady pay beneath Kreldig's ledger.",sp=0}},faq={{q="Who is Kreldig Ungor?",a="Kreldig Ungor is a dwarf operative associated with Reclaimers Inc., based out of the Alliance outpost at Nijel's Point in Desolace. He coordinates salvage missions and specimen gathering across the zone.",al={"kreldig ungor lore","who is kreldig","kreldig ungor"},it="identity"},{q="What is Reclaimers Inc.?",a="Reclaimers Inc. is an entrepreneurial venture focused on salvaging lost cargo, recovering wreckage, and harvesting rare reagents in dangerous frontiers for profit.",al={"reclaimers inc","who are reclaimers inc","reclaimers business"},it="ties"},{q="Where can Kreldig Ungor be found?",a="He is located in the Alliance settlement of Nijel's Point, perched high in the rocky mountains of northeastern Desolace.",al={"kreldig ungor location","where is kreldig","find kreldig ungor"},it="why_here",gp=true},{q="What does Kreldig want with the Karnitol shipwreck?",a="A ship carrying valuable goods belonging to Karnitol wrecked along the Desolace coast. Kreldig employs adventurers to locate the wreck and secure the lost cargo before it is scavenged or destroyed.",al={"karnitol shipwreck","kreldig karnitol","desolace shipwreck"},it="wants"},{q="Why is Kreldig collecting reagents in Desolace?",a="The harsh environment of Desolace fosters rare creatures and unique natural compounds. Kreldig collects these specimens to supply alchemists, artificers, and buyers back in major Alliance cities.",al={"reagents for reclaimers inc","desolace reagents","why collect reagents"},it="motive"},{q="Does Kreldig work for Ironforge or a private enterprise?",a="While he operates from an Alliance outpost and exclusively hires Alliance wanderers, Kreldig represents Reclaimers Inc., a commercial enterprise pursuing salvage and trade rather than official royal military objectives.",al={"kreldig alliance or private","reclaimers inc ironforge"},it="side"},{q="Why is Kreldig Ungor stationed at Nijel's Point?",a="Kreldig Ungor has set up shop high in Nijel's Point to pursue business ventures for Reclaimers Inc. across the rugged expanse of Desolace. From this fortified Alliance refuge, he oversees salvage and procurement operations in relative safety, using it as a base to hire hardy adventurers for ventures down in the perilous wastes.",al={"why is kreldig ungor here","kreldig ungor nijels point","why is kreldig in desolace"},it="why_here",add="ad7684ca"}},ang={["race:Dwarf"]="Kreldig shows off the classic dwarven appetite for rugged frontier exploration and commercial ambition, setting up shop far from the mountain halls.",["faction:Alliance"]="Stationed at Nijel's Point, Kreldig relies entirely on Alliance travelers to keep his salvage contracts moving in an otherwise hostile territory."},kw={"alliance","desolace","dwarf","karnitol shipwreck","kreldig ungor","nijel's point","reclaimers inc","salvage"},rel={"subzone:nijel-s-point","zone:desolace","quest:1453","topic:dwarf"},src={"Kreldig Ungor"}}
E["npc:maurin-bonesplitter"] = {t="npc",n="Maurin Bonesplitter",z="desolace",s="Maurin Bonesplitter is a Forsaken scholar and spellcaster stationed at Ghost Walker Post in Desolace. Appointed by Keldran to monitor demonic cult activity, he leverages his deep understanding of ancient lore to dismantle the Burning Blade. Maurin regards the cultists with sheer contempt, viewing them as fools blind to the dark entities pulling their strings.",h="Maurin Bonesplitter is a Forsaken scholar and spellcaster stationed at Ghost Walker Post in Desolace.",sec={{t="A Scholar Among Outcasts",b="While Ghost Walker Post primarily serves as a tauren and Horde outpost amidst the arid wastes of Desolace, Maurin Bonesplitter stands apart as one of its few undead occupants. Rather than a brutish soldier, Maurin is a learned spellcaster possessing extensive knowledge of forbidden histories and occult forces. His arcane aptitude and sharp intellect caught the eye of Keldran, who dispatched him to the region to observe the growing demonic presence and coordinate targeted strikes against it.",sp=0},{t="Contempt for the Burning Blade",b="Maurin directs most of his malice toward the Burning Blade cult entrenched across Desolace. He harbors utter disgust for their reckless ambition, mocking the cultists for failing to understand that their borrowed power merely binds them as thralls to their demonic masters. Through scrying spells and ritual knowledge, Maurin enlists Horde adventurers to systematically disrupt the cult's summonings and undermine their operations across the barren landscape.",sp=0}},faq={{q="Who is Maurin Bonesplitter?",a="Maurin Bonesplitter is a Forsaken mage and scholar residing at Ghost Walker Post in Desolace. Appointed by Keldran, he uses his knowledge of ancient lore and dark magic to root out the Burning Blade cult operating in the region.",al={"maurin bonesplitter lore","who is maurin","maurin desolace"}},{q="Why is an undead staying at a tauren post?",a="Ghost Walker Post acts as a key Horde settlement in Desolace. Maurin was stationed there by Keldran specifically because the outpost provides an ideal staging ground to observe and combat the Burning Blade cultists infesting the surrounding wilderness.",al={"why is maurin at ghost walker post","undead in desolace"}},{q="What is Maurin's opinion of the Burning Blade?",a="Maurin views the Burning Blade with deep contempt. He sees them as pathetic, ignorant pawns who delusionally believe they wield true power, entirely oblivious to the reality that they are merely puppets of demonic masters.",al={"maurin burning blade","why does maurin hate burning blade"}},{q="Who sent Maurin Bonesplitter to Desolace?",a="Maurin was appointed to his role in Desolace by Keldran. Recognizing Maurin's extensive knowledge of cult practices and ancient lore, Keldran tasked him with actively hindering and eventually eliminating the Burning Blade from the zone.",al={"who sent maurin","maurin keldran","maurin boss"}},{q="What kind of tasks does Maurin give adventurers?",a="Maurin asks adventurers to investigate the Burning Blade and gather a Hatefury Shadowstalker scalp and a naga Oracle Crystal. He uses these reagents to break scrying wards and locate the demon lord behind the cult.",al={"maurin quests","what does maurin want"}},{q="Is Maurin affiliated with the Cenarion Circle or the Horde?",a="Maurin is a loyal member of the Forsaken and serves the Horde. He operates strictly from the Horde encampment at Ghost Walker Post, aiding Horde champions in cleansing the wastes of cultist activity.",al={"is maurin horde","maurin faction"}}},ang={["race:Undead"]="Maurin demonstrates that Forsaken strength relies as much on cunning arcane research and exploiting enemy weaknesses as it does on sheer necromantic might.",["class:Warlock"]="Warlocks will recognize Maurin's acute understanding of demonic pacts, though his disdain serves as a sharp reminder of the peril that comes with serving greater fiends.",["class:Mage"]="Mages visiting Ghost Walker Post can appreciate Maurin's calculated, intellectual approach to unraveling dark rituals with specialized counters.",["faction:Horde"]="Maurin represents Undercity's specialized support to the Horde's western outposts, bringing dark academic knowledge to assist tauren allies against demonic corruption."},kw={"burning blade","corrupter","desolace","forsaken","ghost walker post","keldran","maurin bonesplitter"},rel={"subzone:ghost-walker-post","zone:desolace","npc:keldran","topic:forsaken","quest:1431"},src={"Maurin Bonesplitter"}}
E["npc:misha"] = {t="npc",n="Misha",z="desolace",s="Misha is the loyal bear companion of Rexxar, the Champion of the Horde. Rescued as an orphaned cub, she wanders Kalimdor faithfully at the Mok'nathal beastmaster's side.",h="Misha is the loyal bear companion of Rexxar, the Champion of the Horde.",sec={{t="A Boundless Bond",b="Rexxar discovered Misha as an orphaned cub beside her slain mother in the Ruins of Ravenwind in Feralas. Recognizing a kindred solitary spirit, the wandering Mok'nathal adopted her and gave her a name. Together they ventured north into the arid wilds of Desolace, forging a fierce, protective partnership that has weathered countless wildernesses and bloody battles.",sp=0},{t="Defender of Durotar",b="Misha is far more than a tame pet; she is a seasoned warrior. She fought alongside Rexxar in the brutal conflict against Grand Admiral Daelin Proudmoore at Theramore Isle, helping ensure the young Horde's survival. When not in battle, her keen senses and strength serve as an extension of Rexxar's will, even carrying fallen allies such as the orc Byrok back to Orgrimmar.",sp=0},{t="Wilds of Kalimdor",b="Currently, travelers venturing along the long tracks through the Stonetalon Mountains, Desolace, and Feralas can spot Misha padding quietly beside Rexxar. Though fierce enough to tear apart any predator foolish enough to threaten them, she remains Rexxar's steadfast anchor in an otherwise untrustworthy world.",sp=0}},faq={{q="Who is Misha?",a="Misha is a ferocious brown bear and the lifelong companion of Rexxar, the Champion of the Horde. She wanders the wilds alongside him across central Kalimdor.",al={"rexxars bear","who is the bear with rexxar","misha bear"}},{q="Where did Rexxar find Misha?",a="Rexxar found Misha as a small cub in the Ruins of Ravenwind in Feralas, stranded beside her dead mother. Seeing that they were both alone in the wild, Rexxar took her in.",al={"where did rexxar get misha","misha backstory","how did rexxar meet misha"}},{q="Where can Misha be found right now?",a="Misha roams along the long patrol paths of the Stonetalon Mountains, Desolace, and Feralas, faithfully walking alongside Rexxar on his endless wanderings.",al={"misha location","where is misha","find misha"}},{q="Did Misha take part in the founding of Durotar?",a="Yes. Following the Third War, Misha accompanied Rexxar into battle against Grand Admiral Daelin Proudmoore's forces at Theramore Isle to defend the fledgling Horde.",al={"misha theramore","did misha fight daelin","misha third war"}},{q="Is Misha hostile to Alliance players?",a="Yes. As the companion of the Champion of the Horde, Misha will fiercely defend Rexxar and attack any Alliance trespassers who draw too close.",al={"can alliance attack misha","is misha aggressive"}},{q="Why does Rexxar prefer beasts like Misha to people?",a="Disillusioned by the deceit and warfare of humanoid races, Rexxar chose the solitude of the wilderness. He believes beasts are direct and honest, finding in Misha a companion devoid of betrayal.",al={"why does rexxar keep beasts","rexxar bear companion"}}},ang={["class:Hunter"]="For hunters, Misha represents the ultimate ideal of an animal companion: an unbreakable lifelong partnership forged through mutual respect rather than mere dominance.",["faction:Horde"]="Misha fought alongside Rexxar to secure the fledgling Horde's freedom at Theramore Isle, earning the quiet respect of veterans across Durotar."},kw={"bear","beastmaster","desolace","feralas","misha","ravenwind","rexxar","stonetalon"},rel={"zone:desolace","zone:feralas","zone:stonetalon","subzone:ruins-of-ravenwind","subzone:theramore-isle","zone:orgrimmar","topic:horde","topic:third-war"},src={"Misha"}}
E["npc:taiga-wisemane"] = {t="npc",n="Taiga Wisemane",z="desolace",s="Taiga Wisemane is a tauren elder residing in Shadowprey Village along the rugged western coast of Desolace. Watchful of demonic meddling across the barren wastes, he works to thwart the Burning Blade cult entrenched in the region. He directs Horde champions to disrupt demonic rituals and seal open gateways before the Burning Legion gains ground.",h="Taiga Wisemane is a tauren elder residing in Shadowprey Village along the rugged western coast of Desolace.",sec={{t="A Watchful Eye in Shadowprey",b="Though Shadowprey Village is predominantly a Darkspear troll fishing settlement tucked away against the ocean, Taiga Wisemane has taken up station there to monitor the dark sorceries stirring across Desolace. He remains acutely aware of the spiritual corruption bleeding into the soil, keeping his focus fixed eastward where shadow cults and demonic remnants fester among ancient ruins.",sp=0},{t="Stemming the Demonic Tide",b="The Burning Blade cult operates actively out of Thunder Axe Fortress, experimenting with dark artifacts to widen their influence. Recognizing the peril this poses to all inhabitants of Desolace, Taiga tasks capable adventurers with infiltrating the fortress to claim the Demon Box—an occult chest holding the Hand of Iruxos. Through this severing blow, he aims to rob the cult of the primary focus they rely upon to tear the veil between worlds.",sp=1},{t="Sealing the Coven's Portals",b="Securing the Hand of Iruxos is only the first step of Taiga's plan. At Mannoroc Coven to the south, the Burning Blade has already torn open active demonic rifts. By turning the dark focus against its creators, Taiga directs trusted champions to channel the artifact's energy directly into the gateways, closing the conduits before the Burning Legion can pour reinforcements into the heart of Kalimdor.",sp=1}},faq={{q="Who is Taiga Wisemane?",a="Taiga Wisemane is a tauren elder staying in Shadowprey Village on the western coast of Desolace. He acts as an advisor and quest giver dedicated to tracking and countering demonic rituals enacted by the Burning Blade cult throughout the region.",al={"who is taiga","taiga wisemane lore","taiga shadowprey"}},{q="Why is a tauren living in Shadowprey Village?",a="While Shadowprey is primarily a troll settlement, it is the Horde's main outpost along the Desolace coast. Taiga stays there to keep watch over the desolate wastes and enlist passing Horde travelers to neutralize nearby demonic threats.",al={"why is taiga in shadowprey","taiga troll village","tauren in troll town"}},{q="What is the Burning Blade doing in Desolace?",a="Operating from Thunder Axe Fortress and Mannoroc Coven, the Burning Blade cult is opening demonic gateways to summon forces of the Burning Legion into Kalimdor. Taiga works to undo their efforts before the wasteland is completely overrun.",al={"burning blade desolace","what are the cultists doing","thunder axe fortress cultists"}},{q="What is the Hand of Iruxos?",a="The Hand of Iruxos is a demonic artifact locked within a Demon Box at Thunder Axe Fortress. The Burning Blade means to use its foul energies to pry open portals to the Nether, but Taiga devises a way to turn the hand's magic against the rifts to seal them shut.",al={"hand of iruxos","what is demon box","demon box relic"}},{q="What happens at Mannoroc Coven?",a="Mannoroc Coven is an unholy site in southern Desolace where the Burning Blade successfully established demonic portals. Under Taiga Wisemane's instruction, adventurers take the Hand of Iruxos to the site to forcefully shut down the gateways.",al={"mannoroc coven portals","what is mannoroc coven","desolace portals"}},{q="Does Taiga belong to a specific tauren tribe?",a="Taiga carries the Wisemane surname, reflecting his role as an elder deeply concerned with spiritual balance and demonic corruption, though he serves the wider Horde gathered under the banner of the united tribes.",al={"taiga tribe","wisemane tribe","is taiga bloodhoof"}}},ang={["faction:Horde"]="Taiga provides crucial direction for Horde champions traveling through Desolace, ensuring that the outpost of Shadowprey Village remains shielded from demonic encroachment.",["race:Tauren"]="For tauren travelers, Taiga represents the duty to heal and protect Kalimdor from unnatural demonic blight, standing against the dark legacy that has scarred Desolace.",["class:Warlock"]="Warlocks will find Taiga's understanding of the Hand of Iruxos notable, as he uses the dark relic's own resonance to collapse demonic portals rather than banish them through holy rites."},kw={"burning blade","demon box","desolace","hand of iruxos","mannoroc coven","shadowprey village","taiga wisemane","thunder axe fortress"},rel={"subzone:shadowprey-village","zone:desolace","subzone:thunder-axe-fortress","subzone:mannoroc-coven","topic:tauren","topic:horde"},src={"Taiga Wisemane"}}
E["npc:takata-steelblade"] = {t="npc",n="Takata Steelblade",z="desolace",s="Takata Steelblade is an orc warrior stationed at Ghost Walker Post in Desolace. Dispatched from Orgrimmar by Keldran alongside Maurin Bonesplitter, he spearheads the Horde's local campaign against demonic corruption. His primary focus is eradicating the regional satyr population affiliated with the sinister Burning Blade.",h="Takata Steelblade is an orc warrior stationed at Ghost Walker Post in Desolace.",sec={{t="Sent to Desolace",b="Takata Steelblade was sent from the capital to Desolace under direct orders from Keldran, an influential figure in Orgrimmar committed to uncovering and purging demonic subversion. Operating out of the isolated Tauren encampment of Ghost Walker Post, Takata coordinates military efforts against the Legion-aligned forces plaguing the barren wastes.",sp=0},{t="Scourge of the Satyrs",b="While his companion Maurin Bonesplitter attempts to track and dismantle the clandestine Burning Blade cultists directly, Takata focuses on their demonic allies: the satyrs. Takata has orchestrated aggressive strikes against Desolace's corrupted satyrs, decimating their ranks to break the cult's local power structure and halt their spreading taint.",sp=0}},faq={{q="Who is Takata Steelblade?",a="Takata Steelblade is a veteran orc warrior stationed at Ghost Walker Post in Desolace. He directs operations against demonic forces and satyrs allied with the Burning Blade.",al={"takata","takata lore","who is takata"},it="identity"},{q="Who sent Takata to Desolace?",a="He was sent by Keldran from Orgrimmar to eliminate the threat posed by the Burning Blade and their demonic allies throughout the region.",al={"who sent takata","keldran connection","takata orders"},it="ties"},{q="What is the relationship between Takata and Maurin Bonesplitter?",a="Both were dispatched together by Keldran. While Maurin attempts to counter the Burning Blade cultists directly, Takata focuses his military strikes on the satyrs allied with them.",al={"takata and maurin","maurin bonesplitter"}},{q="Why is Takata hunting satyrs?",a="The satyrs in Desolace are actively allied with the Burning Blade cult, spreading demonic taint and threatening the Horde's foothold across the region.",al={"why kill satyrs","takata satyr","befouled by satyr"},it="wants"},{q="Where can Takata Steelblade be found?",a="He is located at Ghost Walker Post, a Horde camp in north-central Desolace.",al={"takata location","where is takata steelblade"},it="why_here",gp=true},{q="Whose side is Takata Steelblade on?",a="Takata Steelblade is loyal to the Horde and answers to Keldran in Orgrimmar. He works to secure the Horde's interests in Desolace by purging the demonic elements threatening Kalimdor, specifically targeting the wicked cults and demons aligned against his people.",al={"takata steelblade faction","takata loyalty","is takata horde"},it="side",add="a8c99361"},{q="Why is Takata Steelblade here?",a="Takata has taken up post at Ghost Walker Post on the orders of Keldran to lead the local offensive against demonic corruption. While his comrade Maurin Bonesplitter focuses strictly on the Burning Blade cult itself, Takata directs his wrath against the region's satyrs, waging a ruthless campaign to eliminate their presence entirely.",al={"why is takata in desolace","takata steelblade purpose","what is takata doing here"},it="why_here",add="683721f0"},{q="Why is Takata Steelblade famous or feared?",a="Takata is infamous among the foul inhabitants of Desolace for his devastating, systematic massacre of the local satyr population. He has earned a fearsome reputation by aggressively cutting down every satyr affiliated with the Burning Blade across the desolate wastes.",al={"takata reputation","why is takata feared","takata fame"},it="fame",add="a7138bd5"}},ang={["faction:Horde"]="Takata coordinates regional Horde defense in Desolace, working out of Ghost Walker Post to purge demonic infiltrators.",["race:Orc"]="Acting under orders from Orgrimmar's leadership, Takata embodies the orcish duty to stamp out any remnant of demonic servitude.",["class:Warrior"]="A master swordsman, Takata's campaign emphasizes decisive martial force to cut down demonic infiltrators."},kw={"bonesplitter","burning blade","desolace","ghost walker post","keldran","maurin","satyr","steelblade","takata"},rel={"subzone:ghost-walker-post","zone:desolace","npc:keldran","npc:maurin-bonesplitter","topic:satyr","quest:1431"},src={"Takata Steelblade"}}
E["subzone:bolgan-s-hole"] = {t="subzone",n="Bolgan's Hole",z="desolace",s="Bolgan's Hole is a subterranean cavern nestled in the southern cliffs of Gelkis Village in Desolace. It serves as the inner sanctum of the Gelkis centaur clan, housing their highest chieftains and sacred earth relics.",h="Bolgan's Hole is a subterranean cavern nestled in the southern cliffs of Gelkis Village in Desolace.",sec={{t="The Gelkis Seat of Power",b="Carved deep into the craggy bluffs overlooking the Gelkis encampment, Bolgan's Hole functions as the command center for the tribe. It is here that the ruling khan holds court, surrounded by veteran guards and the tribe's most influential shamans. The cavern offers natural fortification against rival clans, most notably the bloodthirsty Magram centaur to the east.",sp=0},{t="Tears of the Earth Princess",b="Beyond its military importance, the cave possesses profound religious significance to the Gelkis. Luminous blue mineral formations known as the tears of Theradras sprout from the damp stone walls. Gelkis shamans obsessively harvest and guard these crystals, revering them as divine blessings that confer the subterranean protection of Princess Theradras, the primal earth elemental mother of the centaur race.",sp=0}},faq={{q="Where is Bolgan's Hole located?",a="Bolgan's Hole is a cave situated in the southern part of Gelkis Village, tucked into the hills of southern Desolace.",al={"bolgans hole location","where is bolgan's hole","bolgan cave entrance"}},{q="Who lives inside Bolgan's Hole?",a="The cave houses the high leadership of the Gelkis centaur, including their clan khan—such as Khan Shaka—as well as their inner circle of protectors and mystical shamans.",al={"who is in bolgan's hole","bolgans hole boss","gelkis khan location"}},{q="What are the glowing blue crystals inside the cave?",a="The crystals are known as the tears of Theradras. The Gelkis revere them as physical manifestations of their earth mother's favor, believing the stones grant mystical protection to those who possess them.",al={"blue crystals in bolgan's hole","tears of theradras","bolgan's hole rocks"}},{q="Can players enter Bolgan's Hole safely?",a="By default, the Gelkis centaur inside are aggressively hostile to outsiders. However, travelers who align themselves with the Gelkis by slaughtering their hated rivals, the Magram clan, can earn standing to walk the cave in peace.",al={"is bolgan's hole hostile","friendly to gelkis","can i go inside bolgans hole"}}},ang={["class:Shaman"]="The cavern offers a grim demonstration of how earth worship can be corrupted when tied to the violent legacy of Princess Theradras rather than the natural balance of the spirits."},kw={"bolgan's hole","centaur","desolace","gelkis","khan shaka","khan shodo","tears of theradras"},rel={"subzone:gelkis-village","topic:centaur","zone:desolace"},src={"Bolgan's Hole"}}
E["subzone:ethel-rethor"] = {t="subzone",n="Ethel Rethor",z="desolace",s="Ethel Rethor is an ancient night elven ruin situated along the rugged northwestern coast of Desolace. While a solitary, sealed tower still rises above the waves, the majority of the sunken settlement now lies submerged in the sea and overrun by hostile naga.",h="Ethel Rethor is an ancient night elven ruin situated along the rugged northwestern coast of Desolace.",sec={{t="A Drowned Relic",b="Perched on the desolate coast of western Kalimdor, Ethel Rethor stands as a haunting reminder of the ancient night elven civilization that flourished before the Great Sundering. Much of the grand architecture has collapsed into the ocean depths, leaving only shattered foundations and a lone, weathered tower protruding from the surf. A small bridge extends toward the tower's sealed portal, but the structure remains shut tight against the elements and intruders alike. The submerged chambers and surrounding shallows have become a stronghold for coastal naga, making the waters treacherous for any who wander near.",sp=0},{t="Watchers on the Shore",b="Despite its remote location and serpentine infestation, Ethel Rethor draws travelers interested in Kalimdor's forgotten histories and ongoing threats. An agent of the Argent Dawn, Azore Aldamort, maintains a watchful presence near the ruins, monitoring the naga menace and offering aid to intrepid adventurers willing to dive into the sunken passages. Between the aquatic dangers offshore and the barren wastes inland, the ruins serve as a lonely coastal crossroads.",sp=0}},faq={{q="What is Ethel Rethor?",a="Ethel Rethor is a ruined night elven coastal settlement in northwestern Desolace. Most of its former structures are now submerged beneath the sea, leaving behind a solitary offshore tower and drowned stonework.",al={"ethel rethor lore","what is this place desolace","ethel rethor ruin"}},{q="Who controls Ethel Rethor now?",a="The sunken ruins and adjacent reefs are occupied by naga. Like many ancient Kaldorei sites along the coast, the serpentine creatures have laid claim to the drowned halls and patrol the surrounding shallows aggressively.",al={"who lives in ethel rethor","ethel rethor monsters","naga at ethel rethor"}},{q="Can you go inside the tower?",a="The tower rising from the sea features a small bridge leading to an entrance, but the doorway remains firmly sealed shut. Travelers can only explore its exterior and dive into the sunken ruins beneath it.",al={"open ethel rethor tower","ethel rethor door","inside ethel rethor"}},{q="Why is the Argent Dawn here?",a="An Argent Dawn representative, Azore Aldamort, is stationed near the ruins. While the Dawn primarily focuses on the Scourge in the east, their operatives across Kalimdor monitor unusual magical disturbances, ancient ruins, and emerging threats like the naga.",al={"argent dawn in desolace","azore aldamor ethel rethor","argent dawn npc desolace"}}},ang={["race:NightElf"]="For night elves, Ethel Rethor is a somber monument to their lost empire, reminding them of the cataclysmic Sundering and the mutated brethren who now prowl the sunken halls.",["faction:Alliance"]="Alliance travelers moving through the hostile barrens of Desolace can find a rare neutral friendly face stationed near the ruins in the Argent Dawn observer Azore Aldamort."},kw={"argent dawn","azore aldamor","desolace","desolace coast","ethel rethor","kaldorei ruins","naga","sunken ruins"},rel={"zone:desolace","topic:naga","topic:argent-dawn","subzone:shadowprey-village"},src={"Ethel Rethor"}}
E["subzone:gelkis-village"] = {t="subzone",n="Gelkis Village",z="desolace",s="Gelkis Village is the primary stronghold of the earth-aligned Gelkis centaur clan in southwestern Desolace. Built around a rugged ravine connected by wooden spans and cliffside paths, the settlement guards the southern route toward Feralas. Its vantage directly overlooks the main north-south road, making it a perilous crossing for any traveler who has not earned the clan's favor.",h="Gelkis Village is the primary stronghold of the earth-aligned Gelkis centaur clan in southwestern Desolace.",sec={{t="A Fortress in the Ravine",b="Gelkis Village sits in a deep, craggy gorge framed by precarious bluffs and rope bridges. Unlike the nomadic raiders of the Barrens, the Gelkis have fortified their ancestral grounds into a permanent settlement, complete with outposts spreading toward the border of Feralas. The heart of the clan's leadership lies within Bolgan's Hole, a cavern carved into the southern cliff face where Khan Shaka oversees his warriors. Travelers trekking south through Desolace must either cut a bloody path through the gorge or tread carefully, as the Gelkis view uninvited wanderers as fair game in their eternal war against their rival centaur brethren.",sp=0}},faq={{q="Who lives in Gelkis Village?",a="The settlement belongs to the Gelkis clan, one of the warring centaur tribes of Desolace. They are staunch earth-worshipers ruled by Khan Shaka, who resides deep in the cliffside cave known as Bolgan's Hole.",al={"gelkis residents","who controls gelkis village","centaur village south"}},{q="Why are the Gelkis centaur hostile to outsiders?",a="Centaur culture is intensely territorial and aggressive toward outsiders. However, the Gelkis hate their rival clan, the Magram, above all else. Adventurers who actively hunt Magram warriors can eventually earn the Gelkis clan's trust and enter the village safely.",al={"why are gelkis attacking","gelkis hostile","can i be friendly with gelkis"}},{q="Where is Gelkis Village located?",a="It is located in southwestern Desolace, just east and slightly south of the troll settlement of Shadowprey Village. Its ravines border the southern mountain face and overlook the trail heading directly south into Feralas.",al={"gelkis location","how to find gelkis village","where is gelkis"}},{q="What is Bolgan's Hole?",a="Bolgan's Hole is a large cavern carved into the southern rock wall of the ravine, connected to the rest of the village via elevated bridges and bluffs. It serves as the inner sanctuary and seat of power for the Gelkis Khan.",al={"bolgans hole","cave in gelkis village","where is gelkis khan"}}},ang={["race:Tauren"]="Centaur drove the tauren from their ancestral lands for generations; seeing the Gelkis fortified in their rocky bastions is a bitter reminder of their enduring threat to Kalimdor.",["faction:Horde"]="With the Darkspear settlement of Shadowprey Village resting directly to the west on the coast, the fortified presence of the Gelkis poses an ongoing threat to nearby Horde operations."},kw={"bolgan's hole","centaur","desolace","feralas","gelkis","khan shaka","magram","shadowprey"},rel={"subzone:bolgan-s-hole","zone:desolace","topic:centaur","subzone:shadowprey-village","zone:feralas"},src={"Gelkis Village"}}
E["subzone:ghost-walker-post"] = {t="subzone",n="Ghost Walker Post",z="desolace",s="Ghost Walker Post is a modest tauren settlement situated in the heart of Desolace right beside the ancient Kodo Graveyard. Far more exposed to regional dangers than Shadowprey Village on the western coast, it serves as a frontline Horde staging ground against centaur clans and the Burning Blade.",h="Ghost Walker Post is a modest tauren settlement situated in the heart of Desolace right beside the ancient...",sec={{t="A Watch on the Wastes",b="Perched on the dusty flats of central Desolace, Ghost Walker Post provides the Horde with an austere foothold in a hostile territory. Unlike the sheltered coastal fishing haven of Shadowprey Village, this post directly faces roaming centaur marauders and demon-worshiping cultists of the Burning Blade. Facilities are spartan, offering only the bare essentials for travelers, with no inn or flight master in sight. Despite the harsh conditions, a garrison of tauren and an orcish detachment sent by Warchief Thrall keep vigilant watch over the badlands.",sp=0},{t="Guardians of the Graveyard",b="Led by the tauren shaman Gurda Wildmane, the spiritual heart of the outpost is closely entwined with the neighboring Kodo Graveyard. Shamans stationed here tend to the dying beasts that wander in to perish, helping ease them into the next life and communing with their lingering spirits. Between spiritual communion and constant military readiness, the defenders of the post honor the ancient bond between the tauren and the mighty kodo amid the ashes of Desolace.",sp=0}},faq={{q="What is Ghost Walker Post?",a="It is a small, rugged Horde outpost located in central Desolace, established primarily by tauren with support from an orcish garrison.",al={"ghost walker post info","what is this camp","horde camp desolace"}},{q="Who leads Ghost Walker Post?",a="The post is led by Gurda Wildmane, a tauren shaman who tends to the camp's defenses and the neighboring Kodo Graveyard.",al={"who is in charge","ghost walker leader","gurda wildmane"}},{q="Why is the post located near the Kodo Graveyard?",a="Gurda Wildmane and fellow tauren shamans reside here to help ease dying kodo into their next lives and to commune with the spirits of the fallen beasts.",al={"why by kodo graveyard","kodo spirits camp","shaman kodo graveyard"}},{q="What enemies does Ghost Walker Post fight?",a="The garrison wages constant war against the local hostile centaur tribes and the sinister forces of the Burning Blade operating across Desolace.",al={"ghost walker enemies","who attacks ghost walker post","post threats"}},{q="Can I get a flight path or rest at an inn here?",a="No. The outpost provides only the bare necessities for adventurers and lacks both an innkeeper and a wind rider master. Travelers must seek transport elsewhere, such as Shadowprey Village.",al={"flight master ghost walker","innkeeper ghost walker","fp here?"}},{q="How does it compare to Shadowprey Village?",a="While Shadowprey Village is a protected troll enclave on the western coast, Ghost Walker Post is inland, heavily exposed to surrounding threats, and focused on frontier defense and spiritual duties.",al={"shadowprey vs ghost walker","other horde camp desolace"}}},ang={["race:Tauren"]="The camp reflects the tauren's deep sacred duty to the natural world, standing as guardians beside the ancestral resting grounds of the kodo.",["class:Shaman"]="Under Gurda Wildmane, the shamans here perform the sacred work of speaking with ancient spirits and easing dying beasts into the spirit world."},kw={"burning blade","centaur","desolace","ghost walker post","gurda wildmane","horde","kodo graveyard","shadowprey village","tauren","thrall"},rel={"zone:desolace","subzone:kodo-graveyard","subzone:shadowprey-village","topic:tauren","topic:horde","topic:centaur","npc:thrall","quest:4767"},src={"Ghost Walker Post"}}
E["subzone:kodo-graveyard"] = {t="subzone",n="Kodo Graveyard",z="desolace",s="The Kodo Graveyard is a sprawling expanse in central Desolace littered with the massive, bleached remains of ancient beasts. By instinct or tradition, aging and dying kodos make a final pilgrimage to this desolate hollow to collapse among the ribs of their ancestors.",h="The Kodo Graveyard is a sprawling expanse in central Desolace littered with the massive, bleached remains of...",sec={{t="Resting Place of Titans",b="Sprawling across the grey earth of Desolace, the Kodo Graveyard holds the colossal skeletons of ancient beasts, some far larger than any living kodo seen today. Dying kodos wander here to spend their final breaths among centuries of accumulated remains. This sacred peace is fragile: scavengers prowl the perimeter, and those who disturb the calcified ribs and skulls risk stirring furious kodo spirits from the dust.",sp=0},{t="A Land of Spirits",b="The boundary between the living and the dead wears exceptionally thin across the bone fields. Travelers who peer into the spirit realm find restless, towering kodo apparitions wandering silently among the dust storms. Nearby, the Horde maintains Ghost Walker Post, watching over the sacred grounds and keeping a wary eye on the wandering herds and spectral manifestations that linger around the bones.",sp=0}},faq={{q="Why do the kodos come here to die?",a="It is an instinctive ritual. When kodos grow ancient, sick, or near death, an innate compulsion drives them across the waste to lie down among the skeletons of their ancestors in this specific corner of Desolace.",al={"why are there bones here","kodo dying grounds","why do kodos gather here"}},{q="Why are some of the skeletons so enormous?",a="Some of the skeletons are much larger than the living kodos seen nearby. Their exact age and origins are not established.",al={"giant kodo bones","huge kodo ribs","massive bones desolace"}},{q="What happens if someone disturbs the bones?",a="Disturbing the remains often provokes the spirits of the dead. Vengeful kodo apparitions readily materialize to attack anyone attempting to scavenge or desecrate the resting place.",al={"looting kodo bones","kodo ghosts","bone collector quest"}},{q="What is Ghost Walker Post?",a="Ghost Walker Post is a small Horde encampment stationed right by the bone fields, allowing Horde travelers to rest, watch over the region's spiritual activity, and guide wanderers through central Desolace.",al={"horde camp near bones","ghost walker camp"}}},ang={["race:Tauren"]="The kodo is a revered partner and spiritual companion to the tauren, making the desecration of these ancestral resting grounds a grave matter.",["profession:Herbalism"]="The decaying remains and spiritual resonance of the graveyard make the area around the large skeletons fertile ground for gathering Grave Moss."},kw={"desolace","ghost walker post","grave moss","kodo bones","kodo graveyard","kodo spirits"},rel={"zone:desolace","subzone:ghost-walker-post","topic:horde"},src={"Kodo Graveyard"}}
E["subzone:kormek-s-hut"] = {t="subzone",n="Kormek's Hut",z="desolace",s="Kormek's Hut is a remote, ramshackle dwelling sitting amid the barren flats of north-central Desolace. Despite its desolate surroundings and mysterious namesake, it currently shelters an eccentric pair: an oddly peaceful cultist and a goblin obsessed with harvesting kodo bones.",h="Kormek's Hut is a remote, ramshackle dwelling sitting amid the barren flats of north-central Desolace.",sec={{t="A Strange Oasis of Oddities",b="Perched out in the arid wastes of north-central Desolace, this small hovel is named after a figure whose whereabouts and identity remain completely unknown. Instead of Kormek, travelers stumbling upon the hut encounter an unusual pairing living out in the middle of nowhere: Willow and Bibbly F'utzbuckle. Inside the hut sits Willow, a member of the otherwise hostile and nihilistic Twilight's Hammer who curiously treats outsiders with calm hospitality. Outside, a pen littered with sun-bleached kodo bones serves as the personal dance floor and staging ground for Bibbly, an excitable goblin captivated by the commercial potential of bone scavenging.",sp=0}},faq={{q="Who is Kormek?",a="No one knows. The hut bears Kormek's name, but neither the goblin outside nor the cultist inside explains who Kormek was, and the namesake is nowhere to be found in the wastes.",al={"who is kormek","kormek identity","where is kormek"}},{q="Why is there a friendly Twilight's Hammer cultist here?",a="Willow resides inside the hut and belongs to the Twilight's Hammer, a cult typically hostile to all mortal life. For reasons of her own, she remains non-aggressive toward travelers who drop by the remote shelter.",al={"willow twilights hammer","why is willow friendly","willow hut"}},{q="What is the goblin outside doing?",a="Bibbly F'utzbuckle spends his days excitedly dancing around an enclosure filled with kodo bones. Like many enterprising goblins, he is thrilled by the prospect of turning ancient desert remains into pure profit.",al={"bibbly futzbuckle","goblin dancing desolace","why is the goblin dancing"}},{q="Where is Kormek's Hut located?",a="The hut lies in north-central Desolace, situated in the dry, windswept flats north of the central crossroads and cemetery grounds.",al={"kormek hut location","where is kormek hut","kormek desolace"}}},kw={"bibbly f'utzbuckle","desolace","kodo bones","kormek","kormek's hut","twilight's hammer","willow"},rel={"zone:desolace","topic:twilight-s-hammer"},src={"Kormek's Hut"}}
E["subzone:magram-village"] = {t="subzone",n="Magram Village",z="desolace",s="Magram Village is the settlement of the Magram centaur clan, situated among foul yellow pools in southeastern Desolace. It serves as the primary base for the Magram as they wage relentless war against their hated rivals, the Gelkis.",h="Magram Village is the settlement of the Magram centaur clan, situated among foul yellow pools in southeastern...",sec={{t="A Stronghold in the Mire",b="Sprawled across islands and shores around stagnant, sulfurous pools in southeast Desolace, Magram Village is a rugged settlement cobbled together with crude wooden bridges and hide tents. The Magram centaur dwell here in constant vigilance against neighboring clans. Known for their sheer brutality and deep-seated animosity toward the southern Gelkis clan, the Magram are willing to tolerate outsiders only if those travelers prove their worth by slaughtering their Gelkis enemies.",sp=0}},faq={{q="Who lives in Magram Village?",a="The village is home to the Magram clan, one of several warring centaur tribes native to Desolace. They live under crude hide canopies on islands connected by rough footbridges.",al={"who is here","magram residents","centaur village"}},{q="Can I enter Magram Village without being attacked?",a="Initially, the Magram centaur are hostile to all outsiders. However, travelers can earn their trust by hunting down and killing their sworn enemies, the Gelkis centaur, to raise standing with the clan.",al={"are magram friendly","magram hostile","how to visit magram village"}},{q="Why are the pools around the village yellow?",a="The pools in and around the village are tainted with sulfur and mineral runoff typical of the barren wastes of Desolace, leaving them stagnant, discolored, and polluted.",al={"yellow water","polluted pools","magram water"}},{q="Why are the Magram fighting the Gelkis?",a="The centaur clans of Desolace share a legendary, bloodthirsty rivalry. The Magram and Gelkis clans in particular have waged a bitter war for dominance over the southern reaches of the wasteland for generations.",al={"magram vs gelkis","centaur blood feud","centaur war"}}},ang={["race:Tauren"]="Centaur savagery has plagued the tribes of Kalimdor for generations, making any settlement of these nomadic marauders an unsettling reminder of past bloodshed."},kw={"centaur","desolace","gelkis","magram","magram village","pools"},rel={"topic:centaur","zone:desolace"},src={"Magram Village"}}
E["subzone:mannoroc-coven"] = {t="subzone",n="Mannoroc Coven",z="desolace",s="Mannoroc Coven is a demon-infested ruin in southern Desolace, named after the pit lord Mannoroth. Settled among ancient night elf architecture, it stands as the largest stronghold of the Burning Legion in central Kalimdor. Cultists of the Burning Blade maintain active summoning portals here, filling the ash-choked land with felhounds, succubi, and infernals.",h="Mannoroc Coven is a demon-infested ruin in southern Desolace, named after the pit lord Mannoroth.",sec={{t="A Bastion of Fel Fire",b="Situated south of Ghost Walker Post and east of Shadowprey Village, Mannoroc Coven blankets the ancient night elf ruins in an oppressive, fel-tainted pall. The coven is commanded on the ground by Lord Azrethoc, alongside the Burning Blade warlock Jugkar Grim'rod. Together, they harness active summoning portals to pull demonic reinforcements straight into Kalimdor, including doomguards, infernals, and felhounds. Even as Horde-aligned travelers attempt to sever these links using relics like the Hand of Iruxos, new rifts continue to tear open through the scarred earth.",sp=0}},faq={{q="Why is this place called Mannoroc Coven?",a="The encampment takes its name in homage to Mannoroth the Destructor, the infamous pit lord who subjugated the orcs through the blood curse and perished in Ashenvale.",al={"who is mannoroc","mannoroc name origin","why named mannoroc"}},{q="Who rules over the coven?",a="Demonic forces here are led by the demon Lord Azrethoc. Mortal interests are directed by Jugkar Grim'rod, a warlock representing the Burning Blade cult.",al={"who leads mannoroc coven","mannoroc coven boss","azrethoc"}},{q="What ruins was the coven built upon?",a="The demonic encampment occupies the crumbling stone foundations of an ancient night elf settlement, long ruined even before the demons flooded the region with fel magic.",al={"what ruins are here","mannoroc ancient ruins","elf ruins desolace"}},{q="How are the demons arriving in Desolace?",a="Burning Blade cultists maintain magical summoning portals across the ruins. These portals draw continuous reinforcements directly from the Twisting Nether, frustrating outside attempts to permanently cleanse the site.",al={"where do demons come from","burning blade portals desolace"}}},ang={["class:Warlock"]="The concentrated fel energy and active Legion summoning rifts make the coven an object of keen tactical interest, offering firsthand observation of raw demonic manifestation.",["race:NightElf"]="Seeing the stonework of your ancient ancestors desecrated and trampled by demonic invaders makes Mannoroc Coven an agonizing reminder of the War of the Ancients."},kw={"azrethoc","burning blade","coven","desolace","felhounds","infernals","jugkar grim'rod","mannoroc"},rel={"zone:desolace","topic:burning-legion","subzone:ghost-walker-post","subzone:shadowprey-village","npc:taiga-wisemane","topic:night-elf"},src={"Mannoroc Coven"}}
E["subzone:nijel-s-point"] = {t="subzone",n="Nijel's Point",z="desolace",s="Nijel's Point is a fortified Alliance and Cenarion Circle redoubt perched high on the northern bluffs of Desolace. Tucked safely away from the blighted valleys below, it serves as the sole safe haven for Alliance travelers, researchers, and soldiers navigating the harsh wasteland.",h="Nijel's Point is a fortified Alliance and Cenarion Circle redoubt perched high on the northern bluffs of...",sec={{t="A Bastion Above the Wastes",b="Carved into the sheer cliffs bordering the Stonetalon Mountains, Nijel's Point stands well above the gray dust and marauding centaur packs of Desolace. The settlement is held by a detachment of the Stormwind Army under Captain Pentigast, charged with monitoring the violent clan wars that threaten Alliance interests across southern Kalimdor. Its high elevation and narrow access trails make it readily defensible, providing a secure staging ground for couriers, scouts, and griffin riders travelling between Stonetalon Peak, Theramore, and Feathermoon Stronghold.",sp=0},{t="Cenarion and Crusade Expeditions",b="Beyond the Stormwind garrison, the outpost shelters emissaries with distinct and perilous agendas. Keeper Marandis and his dryads use the camp as an operational base to confront Princess Theradras deep within Maraudon, seeking to recover the fallen demigod Zaetar. Even the Scarlet Crusade maintains an emissary here in Brother Anton, who seeks to scour the undead ravaging the valley floor. Despite the bustling presence of soldiers and druids, the identity of Nijel himself remains an ancient mystery lost even to those garrisoned atop the ridge.",sp=0}},faq={{q="Why is the Alliance stationed in Desolace?",a="Captain Pentigast leads a Stormwind Army detachment to monitor the warring centaur clans. The Alliance fears that once one clan wipes out the others, the victorious horde will turn its aggression toward neighboring territories and settlements like Stonetalon and Feralas.",al={"why is alliance here","stormwind army in desolace","why nijels point exists"}},{q="Who was Nijel?",a="Nobody at the outpost seems to know. His true history has been lost to time.",al={"who is nijel","nijel lore","who was nijels point named after"}},{q="What is the Cenarion Circle doing at Nijel's Point?",a="Keeper Marandis and his dryad sisters have come to Desolace to purge Maraudon, slay Princess Theradras, and reclaim the remains of Zaetar to return them to the sacred groves of the Stonetalon Mountains.",al={"druids in nijels point","keeper marandis mission","why are dryads here"}},{q="Why is the Scarlet Crusade at Nijel's Point?",a="Brother Anton serves as a distant emissary of the Scarlet Crusade. Brother Crowley in Stormwind sends Alliance adventurers to him, and he tests their resolve against the undead ravagers in Desolace's Valley of Bones.",al={"brother anton scarlet crusade","scarlet crusade in desolace"}}},ang={["faction:Alliance"]="Nijel's Point is your sole fortified refuge and flight staging ground in Desolace, linking supply lines between Stonetalon, Theramore, and Feralas.",["class:Druid"]="Keeper Marandis uses this high mountain sanctuary to organize the reclamation of Zaetar's remains from the corruption festering inside Maraudon."},kw={"brother anton","centaur","desolace","marandis","maraudon","nijel's point","outpost","pentigast"},rel={"zone:desolace","topic:stormwind-army","topic:cenarion-circle","topic:centaur","zone:stonetalon","subzone:feathermoon-stronghold","subzone:theramore-isle","topic:scarlet-crusade"},src={"Nijel's Point"}}
E["subzone:sar-theris-strand"] = {t="subzone",n="Sar'theris Strand",z="desolace",s="Sar'theris Strand forms the western coastline of Desolace, fronting the Veiled Sea. In stark contrast to the barren, grey inland wastes, the shore is sunny and grassy, though it remains perilous due to prowling naga, sea giants, and makrura.",h="Sar'theris Strand forms the western coastline of Desolace, fronting the Veiled Sea.",sec={{t="A Green Edge on a Grey Waste",b="Running the length of western Desolace, Sar'theris Strand offers a bizarre respite from the ash and dust of the inland plains. Here, the clifftops and beaches are bright and green. Yet the strand is far from welcoming: serpentine naga patrol the surf alongside towering sea giants and territorial makrura. Shipwrecks litter the shoals, including the ruined Karnitol vessel to the north and small shattered skiffs beneath the towers of Ethel Rethor, proving the sea is as treacherous as the shore.",sp=0},{t="Wreckage and Rare Waters",b="Beyond the constant threat of naga and giants, the waters off the strand are known among seasoned travelers for their peculiar bounties. The jagged coastal shallows conceal salvage from lost expeditions and merchant ventures, while the deep surf is home to rare marine wildlife, notably the prized Sar'theris Striker fish sought out by master fishermen across Kalimdor.",sp=0}},faq={{q="Why is Sar'theris Strand green when the rest of Desolace is dead?",a="The coastline is sunny and grassy in contrast to the barren, grey interior of Desolace. The source does not explain why this contrast persists.",al={"why green coast","desolace coastline grassy","sar'theris weather"}},{q="What creatures inhabit Sar'theris Strand?",a="The strand is dominated by the amphibious Slitherblade naga, wandering sea giants, and scuttling makrura. Travelers must constantly watch the surf, as patrols roam close to the water's edge.",al={"who lives here","sar'theris mobs","what monsters are on the strand"}},{q="What shipwrecks lie along the shore?",a="The Karnitol Shipwreck sits off the northern waters of the strand, while smaller vessels lie smashed on the beach bluffs beneath the ruined elven towers of Ethel Rethor.",al={"karnitol shipwreck","sunken boats strand","beach wreckage"}},{q="Why do fishermen seek out Sar'theris Strand?",a="The coastal waters here are the exclusive home of the Sar'theris Striker, an elusive fish recognized by renowned angler Nat Pagle as one of the ultimate tests of fishing mastery.",al={"sar'theris striker","fishing coast desolace","nat pagle fish"}}},ang={["profession:Cooking"]="The strand's shores and surrounding waters offer rich marine game, including makrura and rare ocean fish, though cooking fires must be lit under the constant watch of prowling naga."},kw={"desolace","hatecrest","karnitol","makrura","sar'theris","strand","striker"},rel={"zone:desolace","subzone:ethel-rethor","topic:naga","npc:nat-pagle"},src={"Sar'theris Strand"}}
E["subzone:sargeron"] = {t="subzone",n="Sargeron",z="desolace",s="Sargeron is the crumbled ruin of an ancient night elf city located in northern Desolace. Shattered during the Great Sundering, its former temples of Elune have been defiled and claimed by the Hatefury satyrs, who renamed the grounds in tribute to their master, Sargeras.",h="Sargeron is the crumbled ruin of an ancient night elf city located in northern Desolace.",sec={{t="A Defiled Sanctuary",b="Before the War of the Ancients broke the continent, this settlement was a flourishing center of worship dedicated to Elune, housing sacred grounds such as Elune's Temple, Sanctuary, and Cathedral. Its true name is lost to antiquity. When the world shattered, the city collapsed into rubble, leaving behind sanctified relics like the Cup of Elune, Elune's Brazier, and Elune's Handmaiden. In the millennia since, corrupted Hatefury satyrs overran the stones, repurposing the sacred Kaldorei architecture into a stronghold honoring the titan Sargeras.",sp=0}},faq={{q="What was Sargeron called before the Sundering?",a="Its original night elven name has been lost to time. The current name, Sargeron, was given to the ruins by the Hatefury satyrs in homage to the fallen titan Sargeras.",al={"original name","sargeron original name","what was it called"}},{q="Who occupies Sargeron now?",a="The ruins are occupied by the Hatefury satyrs, corrupt demonic beings spawned during the War of the Ancients who actively desecrate the ancient elven sites.",al={"who lives here","sargeron mobs","enemies in sargeron"}},{q="What holy sites were originally located here?",a="The city held several major sites devoted to the Moon Goddess, including Elune's Temple, Elune's Sanctuary, and Elune's Cathedral, which once sheltered revered relics such as the Cup of Elune.",al={"elune temples","holy sites","what buildings were here"}},{q="Why is Sargeron significant to night elves?",a="It serves as a grim reminder of the War of the Ancients and the defilement of Kaldorei holy spaces by demonic forces, harboring ancient elven artifacts that risk being lost or corrupted.",al={"night elf lore sargeron","why do night elves care"}}},ang={["race:NightElf"]="The ruins are a painful sight for any Kaldorei, as sacred altars of Elune are openly defiled by demonic satyrs who mock the goddess in Sargeras's name.",["class:Priest"]="Priests of the Moon will recognize remnants of Elune's Cathedral and holy relics scattered across the broken stones, urging purification."},kw={"cup of elune","desolace","elune","hatefury","kaldorei","sargeras","sargeron","satyr"},rel={"zone:desolace","topic:satyr","topic:elune","topic:sargeras","topic:night-elf","topic:war-of-the-ancients"},src={"Sargeron"}}
E["subzone:shadowbreak-ravine"] = {t="subzone",n="Shadowbreak Ravine",z="desolace",s="Shadowbreak Ravine is a secluded mountain hollow tucked away in southeastern Desolace. Cloaked among jagged crags near Magram Village, this eerie ravine serves as a hidden redoubt for the demonic forces and mortal zealots of the Burning Blade.",h="Shadowbreak Ravine is a secluded mountain hollow tucked away in southeastern Desolace.",sec={{t="A Hidden Enclave of Fel",b="Tucked deep into the barren mountain ridges southeast of Magram Village, Shadowbreak Ravine provides the Burning Blade with a secluded staging ground away from the eyes of wandering centaur tribes. Amid strange, oversized mushrooms and grim ritual encampments, cultists labor alongside summoned demons. Here, dark practitioners invoke fel energies and tend heavy ritual chains, using the natural isolation of the ravine to marshal reinforcements and maintain a firm demonic foothold within the badlands of Desolace.",sp=0}},faq={{q="What is Shadowbreak Ravine?",a="Shadowbreak Ravine is a hidden mountain ravine situated in southeastern Desolace, just beyond Magram Village. It serves as a concealed camp and staging ground for demonic minions and cultists serving the Burning Blade.",al={"shadowbreak ravine info","what is this place","where is shadowbreak ravine"}},{q="Who occupies the ravine?",a="The ravine is occupied by cultists of the Burning Blade working directly alongside demons. They use the ravine's sheltered terrain to perform dark rituals and support their broader offensive across the region.",al={"who lives here","shadowbreak ravine mobs","enemies in shadowbreak ravine"}},{q="What features can be found inside the ravine?",a="The ravine contains dark ritual structures, massive iron chains, and prominent giant mushrooms that sprout amidst the fel-tainted encampments hidden within the mountain clefts.",al={"what is inside shadowbreak ravine","landmarks in shadowbreak ravine"}}},ang={["class:Warlock"]="The dark summoning circles and concentrated fel presence make this secretive canyon a clear testament to the reach of the Burning Blade's dark arts."},kw={"burning blade","cultists","demons","desolace","fel","shadowbreak ravine","magram village"},rel={"zone:desolace","subzone:magram-village","topic:centaur"},src={"Shadowbreak Ravine"}}
E["subzone:shadowprey-village"] = {t="subzone",n="Shadowprey Village",z="desolace",s="Shadowprey Village is a remote Horde fishing settlement built along the rocky southern coast of Sar'theris Strand in Desolace. Populated largely by Darkspear troll fishermen and supported by tauren service keepers, it acts as a critical coastal outpost and trade lifeline amidst a barren wasteland.",h="Shadowprey Village is a remote Horde fishing settlement built along the rocky southern coast of Sar'theris...",sec={{t="A Haven on the Strand",b="Tucked against the cliffs of southern Desolace, Shadowprey Village offers safe harbor in a region notorious for centaur clans and desolate wastes. The settlement is primarily an encampment of troll fishermen whose hauls sustain not only their own village but also inland outposts like Ghost Walker Post. Despite the rough shoreline, towering wooden piers reach out into the ocean, allowing local anglers to brave deep waters and dive for shellfish among the submerged wreckage dotting Sar'theris Strand.",sp=0},{t="Coastal Tribulations",b="Maintaining a frontier port in Desolace is fraught with danger. Beyond the inland threat of marauding centaur, the ocean itself tests the village's survival. Local waters are haunted by ravenous sea life—notably the monstrous orca Blubbergut, who gorges on the fish stocks—and encroachment from violent lobstrok along the southern banks. Tauren allies, including Taiga Wisemane and the keepers of the inn and wind rider roost, help shore up defenses and keep trade routes open across Kalimdor.",sp=0}},faq={{q="Why is Shadowprey Village important to the Horde?",a="Desolace is an inhospitable wasteland lacking natural resources. Shadowprey Village serves as the Horde's sole coastal port in the region, bringing in vital hauls of fish and shellfish to feed garrisons like Ghost Walker Post while offering a wind rider travel hub connected to Stonetalon, Thunder Bluff, and Feralas.",al={"shadowprey purpose","why is shadowprey here","shadowprey horde role"}},{q="Who leads Shadowprey Village?",a="The settlement does not have an official single chieftain. The village operates as a loose community of troll fishermen, with elders like Mai'Lahii handling communication with visitors such as the Cenarion Circle, while tauren residents like Taiga Wisemane oversee coastal security and local defense.",al={"shadowprey leader","who is in charge of shadowprey","mai'lahii"}},{q="Why are there tauren running the services in a troll village?",a="Shadowprey began as an indigenous Darkspear fishing outpost, but its role as a regional supply hub attracted the Horde's broader logistical apparatus. Tauren oversee essential shared infrastructure, maintaining the inn, managing the stables, and directing the wind rider roost connecting the port to Mulgore and beyond.",al={"tauren in shadowprey","why tauren here","shadowprey tauren"}},{q="What threats are troubling the fishermen?",a="Aside from hostile inland centaur, the village contends with a shortage of fish caused by a massive orca named Blubbergut devouring the coastal shoals, alongside encroaching lobstrok swarming the southern tidal flats.",al={"shadowprey problems","blubbergut","shadowprey threats"}}},ang={["race:Troll"]="Shadowprey is a rare haven of Darkspear coastal culture in central Kalimdor, showcasing the tribe's traditional mastery of spearfishing, diving, and coastal survival.",["faction:Horde"]="For Horde travelers trekking through Desolace, Shadowprey Village provides the only coastal rest stop, flight hub, and secure supply base south of the Kodo Graveyard."},kw={"blubbergut","desolace","mai'lahii","sar'theris strand","shadowprey","shadowprey village","taiga wisemane","troll fishing"},rel={"zone:desolace","subzone:sar-theris-strand","subzone:ghost-walker-post","npc:taiga-wisemane","topic:troll","topic:tauren","topic:horde","zone:thunderbluff"},src={"Shadowprey Village"}}
E["subzone:thunder-axe-fortress"] = {t="subzone",n="Thunder Axe Fortress",z="desolace",s="Thunder Axe Fortress is a fortified compound in northwestern Desolace serving as a stronghold for the demonic Burning Blade cult. Within its stone barracks, watchtowers, and darkened caves, cultists perform dark rituals to summon demonic entities and store stolen artifacts of power. The cult remains an active threat to anyone traversing the desolate wastes.",h="Thunder Axe Fortress is a fortified compound in northwestern Desolace serving as a stronghold for the demonic...",sec={{t="A Bastion of the Burning Blade",b="Perched in northwestern Desolace, Thunder Axe Fortress serves as a heavily guarded redoubt for the Burning Blade. Composed of stone barracks, defensive watchtowers, and deep caverns, it allows the cult to maintain a fortified foothold far from the gaze of Kalimdor's major cities. Here, the cultists gather fel energies, summon lesser demons, and concoct schemes to bring far more dangerous entities into the world.",sp=0},{t="Stolen Relics and Dark Summonings",b="The cult stores the Hand of Iruxos at the fortress, a relic linked to the demonic portals of Mannoroc Coven. A Burning Blade seer also studies the stolen Sceptre of Light atop one of the watchtowers. Azore Aldamort asks travelers to recover the sceptre, which is rumored to have been taken from the naga.",sp=1}},faq={{q="Who controls Thunder Axe Fortress?",a="The fortress is held by the Burning Blade cult, an organization devoted to demonic power and the remnants of the Shadow Council. On the ground, the fortress and its operations are overseen by warlocks such as Tyranis Malem.",al={"who runs thunder axe fortress","who is in thunder axe fortress","thunder axe fortress boss"}},{q="What is the Sceptre of Light?",a="The Sceptre of Light is an ancient artifact said to be able to sink entire cities beneath the sea. Azore Aldamort asks travelers to retrieve it from a Burning Blade seer studying it atop one of the fortress's watchtowers.",al={"sceptre of light","scepter of light","stolen naga artifact"},sp=1},{q="How is this fortress connected to Mannoroc Coven?",a="The cultists at Thunder Axe Fortress hold an artifact known as the Hand of Iruxos. This relic was directly linked to the demon portals active at the Mannoroc Coven in southern Desolace, binding their demonic efforts across the zone.",al={"mannoroc coven connection","hand of iruxos"}}},ang={["class:Warlock"]="The Burning Blade's experiments at the fortress demonstrate the reckless bounds of demonology, from binding lesser fiends to forcing planar rifts for greater entities.",["faction:Alliance"]="Investigating Thunder Axe Fortress aligns with Argent Dawn efforts to secure dangerous artifacts like the Sceptre of Light before fel cultists turn them against the continent."},kw={"burning blade","desolace","hand of iruxos","kohor","sceptre of light","thunder axe fortress","tyranis malem"},rel={"zone:desolace","subzone:mannoroc-coven","topic:argent-dawn","topic:naga","topic:light"},src={"Thunder Axe Fortress"}}
E["subzone:valley-of-spears"] = {t="subzone",n="Valley of Spears",z="desolace",s="The Valley of Spears is a rugged canyon nestled in western Desolace, serving as the stronghold of the Maraudine centaur clan. Enclosed by steep cliffs and guarded passes, the valley leads directly to Maraudon, the sacred ancestral burial ground of all centaurkind.",h="The Valley of Spears is a rugged canyon nestled in western Desolace, serving as the stronghold of the...",sec={{t="Stronghold of the Maraudine",b="Carved into the rugged heights of western Desolace, the Valley of Spears is a stronghold of the Maraudine clan. Accessible on foot only through narrow, easily defended mountain passes from the south and east, this enclosed valley provides the centaur with a natural bastion. Travelers who venture past the rocky chokepoints face dense encampments of hostile nomads guarding the approach to their most revered holy site.",sp=0},{t="The Threshold of Maraudon",b="Tucked away at the southwestern end of the valley lies the entrance to Maraudon, the sacred cavern housing the tomb of Zaetar, father of the centaur, where Princess Theradras dwells. Because of this proximity, the Maraudine defend the canyon with zealous fury against rival clans and outside interlopers alike. Anyone foolish enough to stumble into the valley unawares—such as careless gnome cartographers or scouts—frequently ends up captured or slain.",sp=0}},faq={{q="Who controls the Valley of Spears?",a="The valley is the primary territory of the Maraudine clan, one of the warring centaur factions fighting for dominance in Desolace.",al={"who lives here","valley of spears centaur clan","maraudine base"}},{q="Where does the Valley of Spears lead?",a="At the southwestern extremity of the valley lies the entrance to Maraudon, the holy ancestral cavern and burial ground of the centaur race.",al={"how to get to maraudon","maraudon entrance","what is at the end of valley of spears"}},{q="How do you enter the valley?",a="The valley is surrounded by sheer mountain ridges and can only be entered on foot through narrow mountain defiles in the east and south.",al={"valley of spears entrance","how to get in","passes into valley of spears"}},{q="Is anyone trapped in the valley?",a="Yes, an unfortunate gnome named Melizza Brimbuzzle has been taken prisoner by the Maraudine centaur and is held within their camps.",al={"melizza brimbuzzle","captive in valley of spears","gnome prisoner"}}},ang={["race:Tauren"]="Centaur savagery has plagued the tribes of Kalimdor for generations; navigating this stronghold brings the tauren face-to-face with the heart of that ancient enmity.",["faction:Alliance"]="The Alliance keeps a cautious eye on the region, particularly after exploratory travelers like the gnome Melizza Brimbuzzle were captured by the hostile Maraudine clan."},kw={"centaur","desolace","maraudine","maraudon","melizza brimbuzzle","valley of spears"},rel={"zone:desolace","topic:centaur"},src={"Valley of Spears"}}
E["zone:desolace"] = {t="zone",n="Desolace",z="desolace",s="Desolace is a bleak, windswept desert on Kalimdor's western coast, defined by cracked gray earth, constant stormy skies, and the bones of fallen beasts. It is the ancestral cradle of the vicious centaur race and a contested wasteland scarred by ancient Highborne ruins, encroaching demonic cults, and bitter tribal warfare. Both the Horde and Alliance maintain precarious footholds amidst the dust, each seeking to carve out influence while warding off spreading corruption.",h="Desolace is a bleak, windswept desert on Kalimdor's western coast, defined by cracked gray earth, constant...",sec={{t="A Land Cursed and Broken",b="Desolace was not always a barren expanse of ash and yellowed pools. Legend holds that the land withered when the earth elemental Princess Theradras drained the surrounding life force to regenerate her form. Zaetar, son of Cenarius, came to her, but rather than subduing her, he took the princess as his mate. From their unnatural union sprang the first centaur. In shame and bloodthirsty wrath, the newborn race murdered their father and overran the plains, leaving behind the scarred wasteland known today.",sp=0},{t="Warring Hooves",b="The interior of Desolace echoes with the thunder of thousands of hooves as four splintered centaur tribes wage endless war against all interlopers and each other. The Kolkar roam the eastern cliffs, the Magram hold crude yurts around brackish sinkholes, the Gelkis dwell behind rope bridges in deep southern ravines, and the fanatical Maraudine defend the approach to Maraudon itself. Travelers venturing across the wastes frequently find themselves drawn into this ancient blood feud, forced to slaughter one tribe to gain safe passage and tenuous parley with another.",sp=0},{t="Cults and Shadowed Coasts",b="Beyond the warring centaur, darker perils fester along the borders. The Burning Blade cult operates freely out of Thunder Axe Fortress and Shadowbreak Ravine, summoning demons and satyrs that threaten to drown the region in fel fire. Along the stormy shoreline, naga creep onto the beaches of Ethel Rethor, while Darkspear trolls spear fish from the stilted platforms of Shadowprey Village. Tucked high in the northern crags, the Alliance watches from Nijel's Point, suspicious of the Horde's expansion and ever wary of the demonic taint spreading from Mannoroc Coven.",sp=0}},faq={{q="Why is Desolace such a dead wasteland?",a="Legend holds the land was once fertile. The earth elemental Princess Theradras consumed the vitality of the region to rebuild her physical form, and the birth and violent expansion of the centaur shortly after destroyed whatever plant life survived, leaving only gray dust and ash.",al={"why is desolace dead","desolace lore origin"}},{q="Where did the centaur come from?",a="The centaur are the offspring of Zaetar, son of the demigod Cenarius, and the elemental Princess Theradras. Disgusted and enraged by their own twisted appearance, the first khans slew their father immediately after birth and multiplied across the plains in a frenzy of brutality.",al={"centaur origin","who made the centaur","zaetar theradras"}},{q="Can I ally with the centaur tribes here?",a="Yes. Adventurers can earn reputation with either the Gelkis or the Magram tribe by slaying members of their rival clan. Gaining enough standing with one unlocks access to their village, tribal quests, and peace within their territory, though it makes the opposing tribe permanently hostile.",al={"centaur reputation","gelkis or magram","how to befriend centaur"}},{q="What is Maraudon?",a="Maraudon is the sacred ancestral burial ground of the centaur race, hidden deep within the twisting western cliffs of Desolace. It serves as both the tomb of Zaetar and the subterranean lair of Princess Theradras, who continues to channel dark elemental corruption through its cavernous halls.",al={"where is maraudon","maraudon dungeon","what lies under desolace"}},{q="Who is the wanderer roaming Desolace with a bear?",a="That is Rexxar, the Champion of the Horde, accompanied by his loyal bear companion Misha. The Mok'Nathal wanderer patrols the dusty highways of Desolace and the Stonetalon Mountains, keeping a watchful eye on the wilderness and assisting those on vital Horde business.",al={"rexxar desolace","beastmaster in desolace","who is the orc with a bear"}},{q="Why are the Alliance and Horde fighting the Burning Blade here?",a="The Burning Blade cult has taken over strongholds like Thunder Axe Fortress to summon demons and bind felsteeds. The demons and satyrs it calls up threaten a region-wide demonic infestation, a danger both the Horde and the Alliance must answer.",al={"burning blade desolace","thunder axe fortress cultists","why are demons here"}}},ang={["race:Tauren"]="For the tauren, Desolace is sacred and tragic ground. It is the cradle of the centaur, whose scourge drove your people to the brink of extinction.",["class:Warlock"]="The arid plains and demonic sites like Mannoroc Coven draw dark practitioners seeking the secrets of felsteeds, majestic wild horses twisted into fire-breathing horrors through forbidden Shadow Council rites.",["class:Druid"]="Cenarion Circle druids view Desolace as a horrifying scar upon the natural order, where Zaetar met his tragic demise and elemental decay chokes the earth.",["faction:Alliance"]="Operating out of Nijel's Point, the Alliance monitors both the treacherous centaur tribes and the suspicious spread of Horde settlements like Shadowprey Village alongside demonic cults.",["faction:Horde"]="The Horde strives to secure the coastline at Shadowprey Village and protect the kodo herds at Ghost Walker Post, while fighting relentlessly to crush the Burning Blade and prove the modern Horde is free of demonic influence."},kw={"burning blade","centaur","desolace","gelkis","magram","maraudon","nijel's point","shadowprey village","theradras","zaetar"},rel={"subzone:nijel-s-point","subzone:shadowprey-village","subzone:kodo-graveyard","subzone:gelkis-village","subzone:magram-village","subzone:thunder-axe-fortress","subzone:mannoroc-coven","zone:stonetalon"},src={"Desolace (Classic)","Desolace"}}
